    // 3. Convert quaternion to DCM C_BI
    adcs_mat3_t c_bi = adcs_quat_to_dcm_bi(q_bi);

    // 4. Compute P_B = C_BI * P_I * C_BI^T
    // First compute T = C_BI * P_I
    adcs_mat3_t t = adcs_mat3_mul(&c_bi, inertial);

    // Then compute P_B = T * C_BI^T
    adcs_mat3_t c_bi_t = adcs_mat3_transpose(&c_bi);
    adcs_mat3_t p_b = adcs_mat3_mul(&t, &c_bi_t);

    // 5. Calculate trace and symmetry error
    double tr = p_b.m[0][0] + p_b.m[1][1] + p_b.m[2][2];
    double sym_err = fabs(p_b.m[0][1] - p_b.m[1][0]) +
                     fabs(p_b.m[0][2] - p_b.m[2][0]) +
                     fabs(p_b.m[1][2] - p_b.m[2][1]);

    // Check for invalid results (e.g., NaN or Inf from calculation)
    if ((!isfinite(tr)) || (!isfinite(sym_err))) {
        body->m[0][0] = 0.0; body->m[0][1] = 0.0; body->m[0][2] = 0.0;
        body->m[1][0] = 0.0; body->m[1][1] = 0.0; body->m[1][2] = 0.0;
        body->m[2][0] = 0.0; body->m[2][1] = 0.0; body->m[2][2] = 0.0;
        *trace = 0.0;
        *symmetry_error = INFINITY;
        return ADCS_E_RANGE;
    }

    // Assign outputs
    *body = p_b;
    *trace = tr;
    *symmetry_error = sym_err;

    return ADCS_OK;

failure_output:
    // Failure output: zero body matrix and trace, symmetry_error = INFINITY
    for (size_t i = 0; i < 3; ++i) {
        for (size_t j = 0; j < 3; ++j) {
            body->m[i][j] = 0.0;
        }
    }
    *trace = 0.0;
    *symmetry_error = INFINITY;

    return ADCS_E_RANGE;
